import { cn } from "cn";

export function Mark(props: { className?: string }) {
  return (
    <svg viewBox="-6 -6 208 208" aria-hidden className={props.className}>
      <circle cx="98" cy="98" r="93.5" fill="none" stroke="currentColor" strokeWidth="12" />
      <circle cx="98" cy="98" r="64" fill="currentColor" />
      <circle cx="165.4" cy="31.4" r="20" fill="currentColor" />
    </svg>
  );
}

// Seeded so server and client render the same sky.
export function Starfield(props: { count?: number; seed?: number; className?: string }) {
  const random = lcg(props.seed ?? 7);
  const stars = Array.from({ length: props.count ?? 90 }, () => ({
    x: random() * 1920,
    y: random() * 1080,
    r: random() < 0.85 ? 0.8 : 1.6,
    o: 0.25 + random() * 0.6,
  }));
  return (
    <svg
      viewBox="0 0 1920 1080"
      preserveAspectRatio="xMidYMid slice"
      aria-hidden
      className={cn("pointer-events-none absolute inset-0 size-full", props.className)}
    >
      {stars.map((star, i) => (
        <circle
          key={i}
          cx={star.x.toFixed(1)}
          cy={star.y.toFixed(1)}
          r={star.r}
          fill="currentColor"
          fillOpacity={star.o.toFixed(2)}
        />
      ))}
    </svg>
  );
}

export function Eyebrow(props: { children: string; className?: string }) {
  return (
    <p
      className={cn(
        "font-mono text-xs tracking-[0.12em] text-muted-foreground uppercase",
        props.className,
      )}
    >
      {props.children}
    </p>
  );
}

