export function AgentMarks(props: { className?: string }) {
  return (
    <ul className={cn("flex items-center gap-4", props.className)}>
      {agentMarks.map((mark) => (
        <li key={mark.name}>
          <svg viewBox={mark.viewBox} aria-label={mark.name} className="size-6 shrink-0">
            <path d={mark.d} fill={mark.fill} />
          </svg>
        </li>
      ))}
      <li>
        <svg viewBox="0 0 1024 1024" aria-label="Grok" className="size-6 shrink-0">
          {grokPaths.map((d) => (
            <path key={d} d={d} fill="#B9C0C6" />
          ))}
        </svg>
      </li>
    </ul>
  );
}

function lcg(seed: number) {
  const state = { value: seed };
  return () => {
    state.value = (state.value * 16807) % 2147483647;
    return state.value / 2147483647;
  };
}
